import {pieceSVG,names} from './pieces.js';
import {initI18n,t} from './i18n.js';
import {canPreviewCosmetic} from './shop-state.js';
const $=id=>document.getElementById(id),game=new Chess();
const STORAGE='kohaku-game-v1';
let settings={mode:'local',level:2,color:'w',minutes:0},pending={...settings};
let playerColor='w',orientation='w',selected=null,legal=[],hintSquares=[],thinking=false,worker=null,workerId=0;
let result=null,remaining={w:0,b:0},running=false,lastTick=Date.now(),clockHistory=[],toastTimer;
let peer=null,connection=null,roomCode='',onlineRole='',onlineReady=false,hostColor='w';
const DIARY='kohaku-match-diary-v1',moods={calm:['◌','Спокойствие'],joy:['✿','Радость'],focus:['✦','Собранность'],nervous:['〰','Волнение'],tired:['◒','Усталость'],curious:['◇','Любопытство']};
let diary=[],currentMoodBefore='',matchStartedAt=null;
const COSMETICS='kohaku-cosmetics-v1',avatarNames=['Киллуа','Гон','Курапика','Хисока','Леорио','Накрот','Киллуа · портрет','Охотник','Курапика · янтарь','Киллуа · пиксель','Хисока · холод','Курапика · алый','Годжо','Гон · розовый'];
const profile={nickname:'Игрок',avatar:null,created:false,playerId:crypto.randomUUID?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,char=>{const value=crypto.getRandomValues(new Uint8Array(1))[0]%16;return(char==='x'?value:(value&3|8)).toString(16);})};
const defaultCosmetics={design:'mode',palette:'kohaku',board:'classic',avatar:null};
let cosmeticState={owned:[],active:{...defaultCosmetics}},previewCosmetics=null,shopCategory='design';
let purchaseOrders=[],paymentDetails=null,orderSyncPromise=null,dialogRevision=0;
const shopCatalog={
 design:[{id:'classic',title:'Тихая классика',detail:'Скульптурные формы с мягкой гравировкой.',price:399},{id:'poster',title:'Эмбер × Фрост',detail:'Резкие силуэты и контраст двух сторон.',price:399},{id:'origami',title:'Киригами',detail:'Геометрические фигуры с тонкими гранями.',price:399},{id:'kohaku',title:'Кохаку · Волна',detail:'Карпы кои с плавными хвостами и коралловыми пятнами.',price:1799},{id:'wave',title:'Морская гравюра',detail:'Плавные формы и линии волн.',price:399},{id:'lantern',title:'Бумажные фонари',detail:'Лёгкие силуэты с восточными мотивами.',price:399},{id:'moon',title:'Лунный сад',detail:'Спокойные формы, вдохновлённые японским садом.',price:399}],
 palette:[{id:'ember',title:'Эмбер',detail:'Алый и тёплый бордовый.',price:399},{id:'frost',title:'Фрост',detail:'Ледяная бирюза и ночной синий.',price:399},{id:'koi',title:'Сакура',detail:'Пастельная роза и индиго.',price:399},{id:'jade',title:'Карпы кои',detail:'Мятный нефрит и тёмная хвоя.',price:399},{id:'amethyst',title:'Аметист',detail:'Сиреневый шёлк и глубокая слива.',price:399},{id:'coral',title:'Коралловый сад',detail:'Тёплый коралл и сливовая тень.',price:399},{id:'gold',title:'Золотой закат',detail:'Медовый янтарь и ночной шоколад.',price:399},{id:'glacier',title:'Ледник',detail:'Нежная лазурь и глубокий морской синий.',price:399},{id:'plum',title:'Сливовый чай',detail:'Пудровая лаванда и тёмная слива.',price:399}],
 board:[{id:'sakura',title:'Сакура',detail:'Пудровый и ягодный.',price:249},{id:'neon',title:'Неоновые сумерки',detail:'Чернильный и электрический голубой.',price:249},{id:'moss',title:'Моховый сад',detail:'Тёплый кремовый и лесной зелёный.',price:249},{id:'desert',title:'Песчаный берег',detail:'Светлый песок и терракотовый.',price:249},{id:'ice',title:'Зимний пруд',detail:'Молочный лёд и спокойная бирюза.',price:249},{id:'lavender',title:'Лавандовые сумерки',detail:'Сиреневый туман и черничный вечер.',price:249},{id:'autumn',title:'Осенний клён',detail:'Сливочный беж и кленовый красный.',price:249},{id:'midnight',title:'Полночь',detail:'Серебристый туман и тёмный индиго.',price:249}],
 avatar:avatarNames.map((title,index)=>({id:`avatar-${index+1}`,title,detail:'Аватар из вашей коллекции.',price:799}))
};
function loadCosmetics(){try{const saved=JSON.parse(localStorage.getItem(COSMETICS));if(saved&&typeof saved==='object'){profile.nickname=String(saved.nickname||'Игрок').slice(0,24);profile.avatar=saved.avatar||null;profile.created=Boolean(saved.created);profile.playerId=/^[a-f\d]{8}-[a-f\d]{4}-[1-8a-f][a-f\d]{3}-[89ab][a-f\d]{3}-[a-f\d]{12}$/i.test(saved.playerId||'')?saved.playerId:profile.playerId;cosmeticState.active={...defaultCosmetics,...saved.active};}}catch{}}
function saveCosmetics(){try{localStorage.setItem(COSMETICS,JSON.stringify({nickname:profile.nickname,avatar:profile.avatar,created:profile.created,playerId:profile.playerId,active:cosmeticState.active}));return JSON.parse(localStorage.getItem(COSMETICS)).playerId===profile.playerId;}catch{return false;}}
async function apiRequest(method='GET',body){const url=method==='GET'?`/api/orders?playerId=${encodeURIComponent(profile.playerId)}`:'/api/orders';let response;try{response=await fetch(url,{method,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store'});}catch{throw new Error('Нет связи с магазином. Попробуйте ещё раз.');}const data=await apiData(response);if(!response.ok||data.error)throw new Error(data.error||'Не удалось выполнить запрос.');return data;}
async function syncApprovedOrders({silent=true}={}){
 if(!orderSyncPromise)orderSyncPromise=(async()=>{try{
  const data=await apiRequest();let previous={};
  try{const saved=JSON.parse(localStorage.getItem('kohaku-order-status-v1')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))previous=saved;}catch{}
  const catalogIds=new Set(Object.values(shopCatalog).flat().map(item=>item.id));
  const owned=(data.ownedItemIds||[]).filter(id=>catalogIds.has(id)),changed=owned.slice().sort().join(',')!==cosmeticState.owned.slice().sort().join(',');
  cosmeticState.owned=owned;purchaseOrders=data.orders||[];paymentDetails=data.paymentDetails;let notice='';
  for(const order of purchaseOrders){if(order.status==='approved'&&previous[order.id]!=='approved')notice='Заказ одобрен. Предмет добавлен в вашу коллекцию.';if(order.status==='rejected'&&previous[order.id]!=='rejected')notice='Заказ отклонён. Причина указана в разделе «Мои покупки».';previous[order.id]=order.status;}
  try{localStorage.setItem('kohaku-order-status-v1',JSON.stringify(previous));}catch{}
  if(changed){saveCosmetics();renderProfileBadge();render();if($('dialog').open&&$('dialog-content').querySelector('.shop-grid'))renderShop(shopCategory);}
  if($('dialog').open&&$('dialog-content').querySelector('[data-orders-view]')&&!$('dialog-content').querySelector('[data-open-order]:disabled'))renderOrdersView();
  if(notice)toast(notice);return data;
 }finally{orderSyncPromise=null;}})();
 try{return await orderSyncPromise;}catch(error){if(!silent)throw error;return null;}
}
function isCurrentDialog(revision,element){return dialogRevision===revision&&$('dialog').open&&(!element||element.isConnected);}

function selectedCosmetic(key){const value=previewCosmetics?.[key]||cosmeticState.active[key];return value===defaultCosmetics[key]||cosmeticState.owned.includes(value)&&shopCatalog[key]?.some(item=>item.id===value)?value:defaultCosmetics[key];}
function avatarPath(id){return /^avatar-(?:[1-9]|1[0-4])$/.test(id||'')&&cosmeticState.owned.includes(id)?`assets/avatars/${id}.jpg`:'';}
function renderProfileBadge(){const badge=$('profile-avatar'),path=avatarPath(profile.avatar);badge.innerHTML=path?`<img src="${path}" alt="">`:'♙';$('profile-name').textContent=profile.created?profile.nickname:'Создать профиль';}
async function apiData(response){const body=await response.text();if(!body)return{error:'Сервер вернул пустой ответ. Перевод пока не отправляйте.'};try{return JSON.parse(body);}catch{return{error:'Сервис покупок временно недоступен. Перевод пока не отправляйте.'};}}
function cosmeticCard(category,item){const preview=category==='avatar'?`<img src="assets/avatars/${item.id}.jpg" alt="">`:category==='design'?pieceSVG('q','w',item.id,'koi'):category==='palette'?`<span class="palette-swatch ${item.id}"><i></i><i></i></span>`:`<span class="board-swatch ${item.id}"><i></i><i></i><i></i><i></i></span>`;const owned=cosmeticState.owned.includes(item.id),active=owned&&selectedCosmetic(category)===item.id,canPreview=canPreviewCosmetic(category,owned);return `<article class="shop-card ${active?'is-active':''}"><div class="shop-preview">${preview}</div><div class="shop-card-copy"><div class="shop-card-title">${item.title}${active?'<span class="owned-tag">Выбрано</span>':''}</div><p>${item.detail}</p></div><div class="shop-card-actions">${owned?'<span class="free-tag">В коллекции</span>':`<button class="secondary buy-cosmetic" data-category="${category}" data-item="${item.id}">Купить · ${item.price} ₸</button>`}${canPreview?`<button class="secondary preview-cosmetic" data-category="${category}" data-item="${item.id}">${active?'Выбрано':'Примерить'}</button>`:''}</div></article>`;}
const orderLabels={awaiting_payment:'Ожидает оплаты',pending_review:'На проверке',approved:'Одобрена',rejected:'Отклонена'};
function orderDate(value){return new Intl.DateTimeFormat(document.documentElement.lang==='en'?'en-GB':'ru-RU',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));}
function renderOrdersView(){showDialog(`<div data-orders-view><div class="dialog-icon">◇</div><h2>Мои покупки</h2><p>Здесь сохраняются заявки этого профиля. Возвращайтесь к заказу, если закрыли окно оплаты.</p><div class="purchase-list">${purchaseOrders.length?purchaseOrders.map(order=>`<article class="purchase-entry"><div><strong>${escapeHTML(order.itemTitle)} · ${order.amount} ₸</strong><span class="purchase-status" data-status="${escapeHTML(order.status)}">${orderLabels[order.status]||''}</span></div><small>${escapeHTML(order.id)} · ${escapeHTML(orderDate(order.createdAt))}</small>${order.rejectionReason?`<p>${escapeHTML(order.rejectionReason)}</p>`:''}<button class="secondary" data-open-order="${escapeHTML(order.id)}">Открыть заказ</button></article>`).join(''):'<p>У вас пока нет заказов.</p>'}</div><div class="dialog-actions"><button class="secondary" id="refresh-orders">Обновить статус</button><button class="secondary" id="back-to-shop">Назад в магазин</button></div></div>`,{closable:true});$('back-to-shop').onclick=()=>renderShop(shopCategory);$('refresh-orders').onclick=()=>openOrders();$('dialog-content').querySelectorAll('[data-open-order]').forEach(button=>button.onclick=async()=>{const revision=dialogRevision,buttons=[...$('dialog-content').querySelectorAll('[data-open-order]')];buttons.forEach(item=>item.disabled=true);try{await syncApprovedOrders({silent:false});if(!isCurrentDialog(revision,button))return;const order=purchaseOrders.find(entry=>entry.id===button.dataset.openOrder);if(order)renderOrderDetails(order,paymentDetails);else renderOrdersView();}catch(error){if(isCurrentDialog(revision,button))toast(error.message);}finally{if(isCurrentDialog(revision,button))buttons.forEach(item=>item.disabled=false);}});}
async function openOrders(){const revision=showDialog('<h2>Мои покупки</h2><p>Загружаем заявки…</p>');try{await syncApprovedOrders({silent:false});if(isCurrentDialog(revision))renderOrdersView();}catch(error){if(isCurrentDialog(revision))showPaymentError(error);}}
function showPaymentError(error){showDialog(`<div class="dialog-icon">◇</div><h2>Покупка временно недоступна</h2><p>${escapeHTML(error.message||'Сервис заявок временно недоступен.')}</p><p class="payment-limitation">Если вы уже перевели деньги, не отправляйте их повторно. Откройте «Мои покупки» после восстановления связи.</p><div class="dialog-actions"><button id="back-to-shop" class="secondary">Назад в магазин</button></div>`,{closable:true});$('back-to-shop').onclick=()=>renderShop(shopCategory);}
async function renderPaymentRequest(item){const revision=showDialog('<div class="dialog-icon">◇</div><h2>Создаём заказ</h2><p>Регистрируем заявку перед переводом…</p>',{closable:true});if(!saveCosmetics()){showPaymentError(new Error('Разрешите браузеру сохранять данные сайта перед покупкой.'));return;}try{const data=await apiRequest('POST',{itemId:item.id,playerId:profile.playerId,playerName:profile.nickname});paymentDetails=data.paymentDetails;await syncApprovedOrders();if(isCurrentDialog(revision))renderOrderDetails(data.order,paymentDetails);}catch(error){if(isCurrentDialog(revision))showPaymentError(error);}}
function renderOrderDetails(order,payee){const awaiting=order.status==='awaiting_payment';if(awaiting&&(!payee?.phone||!payee?.recipient)){showPaymentError(new Error('Реквизиты недоступны. Перевод пока не отправляйте.'));return;}const orderId=order.id,price=order.amount;const phone=payee?.phone||'',recipient=payee?.recipient||'';const details=document.documentElement.lang==='en'?`Kohaku · order ${orderId}\n${t(order.itemTitle)} — ${price} KZT\nTransfer to ${phone}, recipient ${recipient}.`:`Kohaku · заказ ${orderId}\n${order.itemTitle} — ${price} ₸\nПеревод на номер ${phone}, получатель ${recipient}.`;
showDialog(`<div class="dialog-icon">◇</div><h2>${awaiting?'Перевод за покупку':orderLabels[order.status]}</h2><p><strong>${escapeHTML(order.itemTitle)}</strong> · ${price} ₸</p><div class="transfer-card"><span>Номер заказа</span><strong id="payment-order-id">${escapeHTML(orderId)}</strong>${awaiting?`<span>Перевести через Kaspi или Halyk</span><strong class="transfer-phone">${escapeHTML(phone)}</strong><span>Получатель</span><strong>${escapeHTML(recipient)}</strong>`:''}</div>${awaiting?`<p class="shop-note">Переведите точную сумму по номеру. Сверьте имя получателя в приложении банка. Если есть комментарий, укажите номер заказа.</p><p class="payment-limitation">После перевода укажите данные для сверки. Предмет откроется только после одобрения владельцем. Не вводите номер карты, пароли или SMS-коды.</p><button id="copy-transfer-details" class="secondary">Скопировать реквизиты</button><form id="payment-report-form" class="payment-report-form"><label for="payer-name">Имя отправителя в банковском приложении</label><input id="payer-name" name="payerName" minlength="2" maxlength="80" required autocomplete="name" value="${escapeHTML(order.payerName||'')}"><label for="bank-reference">Номер операции из чека (необязательно)</label><input id="bank-reference" name="bankReference" maxlength="100" value="${escapeHTML(order.bankReference||'')}"><label for="paid-at">Когда перевели (необязательно)</label><input id="paid-at" name="paidAt" type="datetime-local"><button id="send-payment-request" class="primary" type="submit">Я перевёл(а), отправить на проверку</button></form>`:order.status==='pending_review'?'<p class="payment-limitation">Владелец проверяет перевод. Не оплачивайте заказ повторно. После одобрения предмет появится в коллекции.</p>':order.status==='approved'?'<p>Предмет добавлен в вашу коллекцию. Выберите его в магазине или профиле.</p>':`<p>${escapeHTML(order.rejectionReason||'Перевод не найден')}</p><p class="payment-limitation">Если перевод уже отправлен, сохраните чек и уточните причину у получателя. Не переводите повторно.</p>`}<p id="payment-report-status" class="payment-status" role="status"></p><div class="dialog-actions"><button id="view-my-orders" class="secondary">Мои покупки</button><button id="back-to-shop" class="secondary">Назад в магазин</button></div>`,{closable:true});$('back-to-shop').onclick=()=>renderShop(shopCategory);$('view-my-orders').onclick=openOrders;
if(!awaiting)return;
const revision=dialogRevision,form=$('payment-report-form'),status=$('payment-report-status'),button=$('send-payment-request');
$('copy-transfer-details').onclick=async()=>{try{await navigator.clipboard.writeText(details);if(isCurrentDialog(revision,status))toast('Реквизиты и номер заказа скопированы.');}catch{if(isCurrentDialog(revision,status))status.textContent='Выделите и скопируйте реквизиты вручную.';}};
form.onsubmit=async event=>{event.preventDefault();button.disabled=true;try{
 const dateValue=form.querySelector('#paid-at').value,paidAt=dateValue?new Date(dateValue).toISOString():undefined;
 await apiRequest('PATCH',{action:'report',orderId,playerId:profile.playerId,payerName:form.querySelector('#payer-name').value.trim(),bankReference:form.querySelector('#bank-reference').value.trim(),paidAt});
 const reported={...order,status:'pending_review'};purchaseOrders=[reported,...purchaseOrders.filter(entry=>entry.id!==orderId)];
 await syncApprovedOrders();const updated=purchaseOrders.find(entry=>entry.id===orderId);
 if(isCurrentDialog(revision,form))renderOrderDetails(updated&&updated.status!=='awaiting_payment'?updated:reported,paymentDetails);
 }catch(error){if(isCurrentDialog(revision,status))status.textContent=error.message||'Не удалось отправить заявку.';}
 finally{if(isCurrentDialog(revision,form))button.disabled=false;}
};}

function renderShop(category=shopCategory){shopCategory=category;const labels={design:'Дизайн фигур',palette:'Цвет фигур',board:'Цвет доски',avatar:'Аватары'};showDialog(`<div class="dialog-icon">✧</div><h2>Магазин Kohaku</h2><p>Откройте любимый стиль партии. Все цены указаны в тенге.</p><div class="shop-account-actions"><button class="secondary" id="my-orders">Мои покупки</button><button id="reset-preview" class="secondary">Стандартный вид</button></div><div class="shop-tabs">${Object.entries(labels).map(([id,label])=>`<button type="button" data-shop-category="${id}" aria-pressed="${id===shopCategory}">${label}</button>`).join('')}</div><div class="shop-grid">${shopCatalog[shopCategory].map(item=>cosmeticCard(shopCategory,item)).join('')}</div><p class="shop-note">Покупка — ручной перевод. После сообщения о переводе владелец проверит поступление и одобрит или отклонит заказ.</p>`,{closable:true});$('my-orders').onclick=openOrders;$('reset-preview').onclick=()=>{previewCosmetics=null;cosmeticState.active={...defaultCosmetics,avatar:cosmeticState.active.avatar};saveCosmetics();render();renderShop(shopCategory);};$('dialog-content').querySelectorAll('[data-shop-category]').forEach(button=>button.onclick=()=>renderShop(button.dataset.shopCategory));$('dialog-content').querySelectorAll('.buy-cosmetic').forEach(button=>button.onclick=()=>{const item=shopCatalog[button.dataset.category].find(entry=>entry.id===button.dataset.item);if(item)renderPaymentRequest(item);});$('dialog-content').querySelectorAll('.preview-cosmetic').forEach(button=>button.onclick=()=>{const key=button.dataset.category;if(!cosmeticState.owned.includes(button.dataset.item))return;previewCosmetics=null;cosmeticState.active[key]=button.dataset.item;saveCosmetics();$('dialog').close();render();toast('Скин применён и сохранён.');});}
function openProfile(){const ownedAvatars=cosmeticState.owned.filter(id=>/^avatar-(?:[1-9]|1[0-4])$/.test(id));let selectedAvatar=profile.avatar;const options=['<button class="profile-avatar-choice" data-avatar="" aria-pressed="'+(!profile.avatar)+'">♙<small>Стандартный</small></button>',...ownedAvatars.map(id=>`<button class="profile-avatar-choice" data-avatar="${id}" aria-pressed="${profile.avatar===id}"><img src="${avatarPath(id)}" alt=""><small>${avatarNames[Number(id.split('-')[1])-1]}</small></button>`)].join('');showDialog(`<div class="dialog-icon">♙</div><h2>Ваш профиль</h2><p>Профиль сохраняется в этом браузере. Имя и коллекция не синхронизируются между устройствами.</p><label class="profile-label" for="nickname-input">Имя игрока</label><input id="nickname-input" class="profile-input" maxlength="24" value="${escapeHTML(profile.nickname)}" placeholder="Как вас называть?"><div class="profile-collection"><strong>Аватар</strong><div class="profile-avatar-grid">${options}</div>${ownedAvatars.length?'':'<small>Аватары появятся здесь после одобрения заказа.</small>'}</div><p class="profile-stats">Открыто предметов: ${cosmeticState.owned.length} · партий в дневнике: ${diary.length}</p><div class="dialog-actions"><button id="save-profile" class="primary">Сохранить профиль</button></div>`,{closable:true});$('dialog-content').querySelectorAll('[data-avatar]').forEach(button=>button.onclick=()=>{$('dialog-content').querySelectorAll('[data-avatar]').forEach(option=>option.setAttribute('aria-pressed',String(option===button)));selectedAvatar=button.dataset.avatar||null;});$('save-profile').onclick=()=>{profile.nickname=$('nickname-input').value.trim().slice(0,24)||'Игрок';profile.avatar=selectedAvatar;profile.created=true;cosmeticState.active.avatar=profile.avatar;saveCosmetics();renderProfileBadge();render();$('dialog').close();toast('Профиль сохранён в этом браузере.');};}
function setSelect(name,value){const root=document.querySelector(`[data-select="${name}"]`),trigger=$(name+'-trigger'),label=$(name+'-value');if(!root)return;const option=root.querySelector(`[data-value="${value}"]`),labels=name==='color'?{w:'○ Белые',b:'● Чёрные',random:'◐ Случайно'}:{0:'Без спешки ∞',5:'5 минут',10:'10 минут',15:'15 минут'};if(option)label.textContent=labels[value]||option.textContent;root.querySelectorAll('[role="option"]').forEach(el=>el.setAttribute('aria-selected',String(el===option)));}
function closeSelects(){document.querySelectorAll('.custom-select').forEach(root=>{root.querySelector('.select-menu').hidden=true;root.querySelector('.select-trigger').setAttribute('aria-expanded','false');});}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3600);}
function save(){if(settings.mode==='online')return;try{localStorage.setItem(STORAGE,JSON.stringify({moves:game.history(),settings,playerColor,orientation,result,remaining,running,clockHistory,currentMoodBefore,matchStartedAt}));}catch{}}
function restore(){try{const saved=JSON.parse(localStorage.getItem(DIARY));diary=Array.isArray(saved)?saved:[];}catch{diary=[];}try{const data=JSON.parse(localStorage.getItem(STORAGE));if(!data||!Array.isArray(data.moves))return;for(const move of data.moves)game.move(move);settings={...settings,...data.settings,mode:'local'};pending={...settings};playerColor=data.playerColor==='b'?'b':'w';orientation=data.orientation==='b'?'b':'w';remaining=data.remaining;clockHistory=data.clockHistory||[];result=data.result;currentMoodBefore=data.currentMoodBefore||'';matchStartedAt=data.matchStartedAt||null;running=Boolean(data.running)&&!result&&!game.isGameOver();lastTick=Date.now();}catch{game.reset();result=null;running=false;}}
function escapeHTML(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
function moodOptions(){return `<div class="mood-grid">${Object.entries(moods).map(([id,[icon,label]])=>`<button type="button" class="mood-option" data-mood="${id}" aria-pressed="false"><span>${icon}</span>${label}</button>`).join('')}</div>`;}
function bindMoodOptions(root,onChoose){root.querySelectorAll('[data-mood]').forEach(button=>button.onclick=()=>{root.querySelectorAll('[data-mood]').forEach(option=>option.setAttribute('aria-pressed',String(option===button)));onChoose(button.dataset.mood);});}
function showBeforeMood(onContinue){let choice='';showDialog(`<div class="dialog-icon">◌</div><h2>С каким настроением начнём?</h2><p>Отметка поможет заметить, как партии влияют на ваше состояние.</p><div id="before-moods">${moodOptions()}</div><div class="dialog-actions"><button id="start-with-mood" class="primary" disabled>Начать партию ↗</button><button id="start-without-mood" class="secondary">Начать без отметки</button></div>`,{closable:false});bindMoodOptions($('before-moods'),mood=>{choice=mood;$('start-with-mood').disabled=false;});$('start-with-mood').onclick=()=>{$('dialog').close();onContinue(choice);};$('start-without-mood').onclick=()=>{$('dialog').close();onContinue('');};}
function saveDiaryEntry(moodAfter,note){const entry={id:crypto.randomUUID?.()||String(Date.now()),date:new Date().toISOString(),mode:settings.mode==='bot'?'Игра с ботом':settings.mode==='online'?'Онлайн с другом':'С другом',outcome:result?.title||'Партия завершена',moodBefore:currentMoodBefore,moodAfter,note:note.trim().slice(0,240),moves:game.history().length,startedAt:matchStartedAt};diary.unshift(entry);diary=diary.slice(0,100);try{localStorage.setItem(DIARY,JSON.stringify(diary));}catch{}renderDiary();}
function renderDiary(){if(!$('diary-list'))return;$('diary-count').textContent=diary.length;$('diary-list').innerHTML=diary.length?diary.map(entry=>`<article class="diary-entry"><div class="diary-entry-head"><strong class="diary-entry-title">${escapeHTML(entry.outcome)}</strong><time class="diary-entry-date">${new Date(entry.date).toLocaleDateString(document.documentElement.lang==='en'?'en-US':'ru-RU',{day:'numeric',month:'short',year:'numeric'})}</time></div><p class="diary-entry-meta">${escapeHTML(entry.mode)} · ${Math.ceil(entry.moves/2)} ${Math.ceil(entry.moves/2)===1?'ход':'ходов'}</p><div class="diary-entry-moods">${entry.moodBefore&&moods[entry.moodBefore]?`<span class="diary-mood-chip">До: ${moods[entry.moodBefore][0]} ${moods[entry.moodBefore][1]}</span>`:''}${entry.moodAfter&&moods[entry.moodAfter]?`<span class="diary-mood-chip">После: ${moods[entry.moodAfter][0]} ${moods[entry.moodAfter][1]}</span>`:''}</div>${entry.note?`<p class="diary-entry-note">${escapeHTML(entry.note)}</p>`:''}</article>`).join(''):'<div class="diary-empty">Здесь будут ваши партии и настроение до и после.<br>Перед следующей игрой отметьте, как вы себя чувствуете.</div>';}
function openPanel(name){for(const other of ['settings','history','diary']){$(other+'-tab').setAttribute('aria-selected',String(name===other));$(other+'-panel').hidden=name!==other;}renderHistory();renderDiary();}
function cancelWorker(){worker?.terminate();worker=null;thinking=false;workerId++;document.body.classList.remove('thinking');}
function syncSettings(){document.querySelectorAll('[data-mode]').forEach(b=>{const on=b.dataset.mode===pending.mode;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on);});document.querySelectorAll('[data-level]').forEach(b=>{const on=Number(b.dataset.level)===pending.level;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on);});setSelect('color',pending.color);setSelect('time',pending.minutes);$('difficulty-field').hidden=pending.mode!=='bot';$('color-field').hidden=pending.mode==='local';$('online-panel').hidden=pending.mode!=='online';$('level-note').textContent=['','Для знакомства с игрой. Иногда ошибается.','Продумывает ответ. Держит в тонусе.','Ищет комбинации. Потребует внимания.'][pending.level];$('settings-note').textContent=pending.mode==='online'?'Создайте комнату и отправьте другу ссылку или код.':JSON.stringify(pending)===JSON.stringify(settings)?'Вдохните. Сделайте первый ход.':'Настройки применятся в новой партии.';$('new-game').hidden=pending.mode==='online';$('new-game').innerHTML='Новая игра <span>↗</span>';}
function endState(){if(result)return result;if(game.isCheckmate())return {title:game.turn()==='w'?'Победа чёрных':'Победа белых',detail:'Мат. Королю больше некуда отступать.'};if(game.isStalemate())return {title:'Ничья — пат',detail:'Нет допустимых ходов, но король не под шахом.'};if(game.isThreefoldRepetition())return {title:'Ничья',detail:'Позиция повторилась три раза.'};if(game.isInsufficientMaterial())return {title:'Ничья',detail:'Недостаточно фигур для мата.'};if(game.isDraw())return {title:'Ничья',detail:'Правило 50 ходов без взятий и ходов пешек.'};return null;}
function statusText(){const end=endState();if(end)return end.title;if(thinking)return 'Кои обдумывает ход…';if(settings.mode==='online'&&!onlineReady)return connection?'Подключаем друга…':'Создайте комнату или введите код';if(game.isCheck())return `Шах! ${game.turn()==='w'?'Ход белых':'Ход чёрных'}`;if(settings.mode==='bot')return game.turn()===playerColor?'Ваш ход':'Ход бота Кои';if(settings.mode==='online')return game.turn()===playerColor?'Ваш ход':'Ход друга';return game.turn()==='w'?'Ход белых':'Ход чёрных';}
function renderBoard(){const nowLocal=settings.mode!=='bot';document.body.classList.toggle('local-match',nowLocal);document.body.dataset.boardSkin=selectedCosmetic('board')||'classic';document.body.dataset.pieceDesign=selectedCosmetic('design')||'mode';document.body.dataset.piecePalette=selectedCosmetic('palette')||'kohaku';const focused=document.activeElement?.dataset?.square;const files=orientation==='w'?'abcdefgh':'hgfedcba';const ranks=orientation==='w'?[8,7,6,5,4,3,2,1]:[1,2,3,4,5,6,7,8];const last=game.history({verbose:true}).at(-1);let html='';for(const [ri,rank]of ranks.entries())for(const [fi,file]of [...files].entries()){const square=file+rank,piece=game.get(square);const available=legal.some(m=>m.to===square);const dark=(file.charCodeAt(0)-97+rank)%2===1;const classes=['square',dark?'dark':'',last&&(last.from===square||last.to===square)?'last':'',selected===square?'selected':'',available?'legal':'',available&&piece?'capture':'',hintSquares.includes(square)?'hint':'',piece?.type==='k'&&piece.color===game.turn()&&game.isCheck()?'check':''].filter(Boolean).join(' ');const label=`${square}${piece?`, ${piece.color==='w'?'белые':'чёрные'}: ${names[piece.type]}`:', пусто'}${available?', доступный ход':''}`;html+=`<button class="${classes}" data-square="${square}" aria-label="${label}" aria-pressed="${selected===square}">${ri===7?`<span class="coord file">${file}</span>`:''}${fi===0?`<span class="coord rank">${rank}</span>`:''}${piece?pieceSVG(piece.type,piece.color,selectedCosmetic('design')||'mode',selectedCosmetic('palette')||'kohaku'):''}</button>`;}$('board').innerHTML=html;if(focused)$('board').querySelector(`[data-square="${focused}"]`)?.focus({preventScroll:true});}
function renderPlayers(){const top=orientation==='w'?'b':'w',bottom=orientation;for(const [where,color]of [['top',top],['bottom',bottom]]){const bot=settings.mode==='bot'&&color!==playerColor,isSelf=settings.mode==='bot'&&color===playerColor||settings.mode==='online'&&color===playerColor;$(where+'-name').textContent=settings.mode==='local'?(color==='w'?'Белые':'Чёрные'):bot?'Бот Кои':settings.mode==='online'?(isSelf?profile.nickname:'Друг'):profile.nickname;$(where+'-detail').textContent=bot?`${['','Лёгкий','Средний','Сложный'][settings.level]} уровень · ${color==='w'?'белые':'чёрные'}`:`${color==='w'?'Белые':'Чёрные'} фигуры`;const avatar=$(where+'-player').querySelector('.avatar');avatar.className='avatar '+(bot?'bot-avatar':'human-avatar');const path=isSelf?avatarPath(profile.avatar):'';avatar.innerHTML=path?`<img src="${path}" alt="">`:bot?'✦':settings.mode==='local'?(color==='w'?'♙':'♟'):'♙';}renderClocks();}
function renderClocks(){for(const where of ['top','bottom']){const color=where==='bottom'?orientation:orientation==='w'?'b':'w';const seconds=Math.max(0,Math.ceil(remaining[color]/1000));const clock=$(where+'-clock');clock.hidden=!settings.minutes;clock.textContent=settings.minutes?`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`:'';clock.classList.toggle('active',game.turn()===color&&!endState());clock.classList.toggle('low',Boolean(settings.minutes&&seconds<30));}}
function renderHistory(){const moves=game.history();$('move-count').textContent=moves.length;$('history').innerHTML=moves.length?Array.from({length:Math.ceil(moves.length/2)},(_,i)=>`<div class="history-row"><span>${i+1}.</span><span>${moves[i*2]}</span><span>${moves[i*2+1]||'—'}</span></div>`).join(''):'<div class="empty-history">Пока здесь чистый лист.<br>Ваша история начнётся с первого хода.</div>';$('history').scrollTop=$('history').scrollHeight;$('export').disabled=!moves.length;}
function render(){renderBoard();renderPlayers();renderHistory();renderDiary();$('status').textContent=statusText();$('game-mode').textContent=settings.mode==='bot'?'✦ Игра с ботом':settings.mode==='online'?'↗ Онлайн-партия':'♙ Игра вдвоём';$('undo').disabled=!game.history().length||Boolean(result)||settings.mode==='online';$('hint').disabled=Boolean(endState())||thinking||settings.mode==='bot'&&game.turn()!==playerColor||settings.mode==='online'&&(!onlineReady||game.turn()!==playerColor);$('resign').disabled=Boolean(endState())||!game.history().length;$('new-game').disabled=settings.mode==='online'&&onlineRole==='guest';document.body.classList.toggle('thinking',thinking);}
function showDialog(html,{closable=true}={}){dialogRevision++;$('dialog-content').innerHTML=html;$('dialog-close').hidden=!closable;$('dialog').dataset.closable=String(closable);if(!$('dialog').open)$('dialog').showModal();return dialogRevision;}
function finish(end,{remote=false}={}){if(result)return;result=end;running=false;cancelWorker();if(settings.mode==='online'&&!remote)sendOnline({type:'end',end});save();render();showDialog(`<div class="dialog-icon">${end.title.includes('Ничья')?'◐':'♔'}</div><h2>${end.title}</h2><p>${end.detail}</p><section class="diary-checkin"><p>Как вы себя чувствуете после партии?</p><div id="after-moods">${moodOptions()}</div><label class="sr-only" for="diary-note">Заметка о партии</label><textarea id="diary-note" class="diary-note-input" maxlength="240" placeholder="Заметка: что запомнилось в этой партии? (необязательно)"></textarea><small>Запись останется только в этом браузере.</small></section><div class="dialog-actions diary-actions"><button id="save-diary" class="primary" disabled>Записать в дневник</button><button id="review-game" class="secondary">Посмотреть доску</button><button id="play-again" class="secondary">${settings.mode==='online'?'Закрыть':'Сыграть ещё'}</button></div>`);let moodAfter='';bindMoodOptions($('after-moods'),mood=>{moodAfter=mood;$('save-diary').disabled=false;});$('save-diary').onclick=()=>{saveDiaryEntry(moodAfter,$('diary-note').value);$('dialog').close();openPanel('diary');toast('Партия сохранена в дневнике.');};$('review-game').onclick=()=>$('dialog').close();$('play-again').onclick=()=>$('dialog').close()||((settings.mode==='online')?closeRoom():newGame());}
function tick(){const now=Date.now(),elapsed=now-lastTick;lastTick=now;if(!running||!settings.minutes||endState())return;remaining[game.turn()]=Math.max(0,remaining[game.turn()]-elapsed);if(remaining[game.turn()]<=0){const loser=game.turn();finish({title:loser==='w'?'Победа чёрных':'Победа белых',detail:`У ${loser==='w'?'белых':'чёрных'} закончилось время.`});return;}renderClocks();}
function makeMove(move,{remote=false,clock=null}={}){tick();if(endState())return;const snapshot={...remaining};let played;try{played=game.move(move);}catch{return;}clockHistory.push(snapshot);if(clock)remaining=clock;selected=null;legal=[];hintSquares=[];running=true;lastTick=Date.now();if(settings.mode==='online'&&!remote)sendOnline({type:'move',move:{from:played.from,to:played.to,promotion:played.promotion},remaining});save();render();const end=endState();if(end){finish(end);return;}requestBot();}
function requestBot(){if(settings.mode!=='bot'||game.turn()===playerColor||endState())return;thinking=true;render();runWorker(settings.level,move=>{thinking=false;if(move)makeMove(move);});}
function runWorker(level,onMove){worker?.terminate();const id=++workerId;const fen=game.fen();try{worker=new Worker(new URL('./bot-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.id!==workerId||game.fen()!==fen)return;worker?.terminate();worker=null;if(data.error){workerFailure();return;}onMove(data.move);render();};worker.onerror=()=>workerFailure();worker.postMessage({id,fen,level});}catch{workerFailure();}}
function workerFailure(){cancelWorker();if(settings.mode==='bot'&&game.turn()!==playerColor&&!endState()){const moves=game.moves();if(moves.length){makeMove(moves[Math.floor(Math.random()*moves.length)]);toast('Бот временно использует простой режим.');}}else{render();toast('Подсказка сейчас недоступна.');}}
function clickSquare(square){if(endState()||thinking||settings.mode==='bot'&&game.turn()!==playerColor||settings.mode==='online'&&(!onlineReady||game.turn()!==playerColor))return;const options=legal.filter(m=>m.to===square);if(selected&&options.length){const from=selected;if(options.some(m=>m.promotion)){showDialog(`<h2>Время превратиться</h2><p>Выберите фигуру для вашей пешки.</p><div class="promotions">${['q','r','b','n'].map(type=>`<button data-promote="${type}" aria-label="${names[type]}">${pieceSVG(type,game.turn())}</button>`).join('')}</div>`,{closable:false});$('dialog-content').querySelectorAll('[data-promote]').forEach(b=>b.onclick=()=>{$('dialog').close();makeMove({from,to:square,promotion:b.dataset.promote});});return;}makeMove({from,to:square});return;}const piece=game.get(square);selected=piece?.color===game.turn()&&selected!==square?square:null;legal=selected?game.moves({square:selected,verbose:true}):[];hintSquares=[];renderBoard();}
$('board').onclick=e=>{const cell=e.target.closest('[data-square]');if(cell)clickSquare(cell.dataset.square);};
$('board').onkeydown=e=>{const keys={ArrowLeft:-1,ArrowRight:1,ArrowUp:-8,ArrowDown:8};if(e.key==='Escape'){selected=null;legal=[];renderBoard();}if(!(e.key in keys))return;e.preventDefault();const cells=[...$('board').children],i=cells.indexOf(document.activeElement);cells[Math.max(0,Math.min(63,i+keys[e.key]))]?.focus();};
function newGame(){if(pending.mode==='online'&&!(onlineRole==='host'&&onlineReady)){toast('Сначала создайте комнату и дождитесь подключения друга.');return;}showBeforeMood(mood=>{currentMoodBefore=mood;matchStartedAt=Date.now();if(pending.mode==='online'){sendOnline({type:'rematch'});resetOnlineGame(hostColor);return;}if(settings.mode==='online')closeRoom();cancelWorker();game.reset();settings={...pending};playerColor=settings.color==='random'?(Math.random()<.5?'w':'b'):settings.color;orientation=settings.mode==='local'?'w':playerColor;selected=null;legal=[];hintSquares=[];result=null;remaining={w:settings.minutes*60000,b:settings.minutes*60000};running=false;lastTick=Date.now();clockHistory=[];syncSettings();save();render();requestBot();});}
function resetOnlineGame(color){game.reset();settings={...pending,mode:'online',color};playerColor=color;orientation=color;selected=null;legal=[];hintSquares=[];thinking=false;result=null;remaining={w:settings.minutes*60000,b:settings.minutes*60000};running=false;lastTick=Date.now();clockHistory=[];onlineReady=true;render();}
function sendOnline(message){if(connection?.open)try{connection.send(message);}catch{toast('Связь прервалась. Попробуйте подключиться снова.');}}
function roomMessage(message){if(!message||typeof message!=='object')return;if(message.type==='hello'&&onlineRole==='host'){onlineReady=true;sendOnline({type:'state',hostColor,minutes:settings.minutes,moves:game.history(),remaining,running,result});$('room-status').textContent='Друг подключился';render();return;}if(message.type==='state'&&onlineRole==='guest'){pending={...pending,mode:'online',minutes:Number(message.minutes)||0};hostColor=message.hostColor==='b'?'b':'w';playerColor=hostColor==='w'?'b':'w';orientation=playerColor;game.reset();for(const move of message.moves||[])game.move(move);settings={...pending,mode:'online',color:playerColor};remaining=message.remaining||{w:settings.minutes*60000,b:settings.minutes*60000};running=Boolean(message.running);result=message.result||null;clockHistory=[];lastTick=Date.now();selected=null;legal=[];hintSquares=[];onlineReady=true;$('room-status').textContent='Вы подключились · партия началась';render();return;}if(message.type==='move'&&onlineRole){if(message.remaining&&typeof message.remaining==='object')remaining=message.remaining;makeMove(message.move,{remote:true,clock:message.remaining});return;}if(message.type==='end'&&message.end)finish(message.end,{remote:true});if(message.type==='rematch'&&onlineRole==='guest'){showBeforeMood(mood=>{currentMoodBefore=mood;matchStartedAt=Date.now();resetOnlineGame(playerColor);});}}
function bindConnection(conn){connection=conn;conn.on('open',()=>{if(onlineRole==='guest'){conn.send({type:'hello'});$('room-card').hidden=false;$('room-status').textContent='Подключаемся к партии…';$('room-code-display').textContent=roomCode.toUpperCase();}render();});conn.on('data',roomMessage);conn.on('close',()=>{onlineReady=false;connection=null;if($('room-card')&&!$('room-card').hidden)$('room-status').textContent='Связь закрыта';render();});conn.on('error',()=>{onlineReady=false;toast('Не удалось связаться с этой комнатой. Проверьте код.');render();});}
function closeRoom(){try{connection?.close();peer?.destroy();}catch{}connection=null;peer=null;roomCode='';onlineRole='';onlineReady=false;$('room-card').hidden=true;$('room-code').value='';if(new URLSearchParams(location.search).has('room'))history.replaceState(null,'',location.pathname+location.hash);render();}
function makeRoomCode(){const chars='abcdefghjkmnpqrstuvwxyz23456789',bytes=crypto.getRandomValues(new Uint8Array(8));return [...bytes].map(v=>chars[v%chars.length]).join('');}
function startRoom(){showBeforeMood(createRoomNow);}
function createRoomNow(mood){currentMoodBefore=mood;matchStartedAt=Date.now();closeRoom();pending.mode='online';syncSettings();onlineRole='host';roomCode=makeRoomCode();hostColor=pending.color==='random'?(Math.random()<.5?'w':'b'):pending.color;resetOnlineGame(hostColor);$('room-card').hidden=false;$('room-code-display').textContent=roomCode.toUpperCase();$('room-status').textContent='Ожидаем друга…';const PeerClient=window.Peer;if(!PeerClient){closeRoom();toast('Не удалось загрузить онлайн-подключение. Обновите страницу.');return;}peer=new PeerClient('kohaku-'+roomCode);peer.on('open',()=>{render();});peer.on('connection',conn=>{if(connection?.open){conn.close();return;}bindConnection(conn);});peer.on('error',err=>{if(err.type==='unavailable-id'){closeRoom();toast('Такой код уже занят. Создайте новую комнату.');}else{toast('Онлайн-связь временно недоступна. Попробуйте ещё раз.');}});$('room-code').value=roomCode;}
function startJoiningRoom(raw){showBeforeMood(mood=>joinRoomNow(raw,mood));}
function joinRoomNow(raw,mood){const code=String(raw||'').trim().toLowerCase().replace(/[^a-z0-9]/g,'');if(code.length<6||code.length>16){toast('Введите код приглашения из ссылки или сообщения.');return;}currentMoodBefore=mood;matchStartedAt=Date.now();closeRoom();pending.mode='online';syncSettings();onlineRole='guest';roomCode=code.replace(/^kohaku-/,'');const inviteUrl=new URL(location.href);inviteUrl.searchParams.set('room',roomCode);history.replaceState(null,'',inviteUrl);game.reset();settings={...pending,mode:'online'};result=null;onlineReady=false;$('room-card').hidden=false;$('room-code-display').textContent=roomCode.toUpperCase();$('room-status').textContent='Ищем комнату…';const PeerClient=window.Peer;if(!PeerClient){closeRoom();toast('Не удалось загрузить онлайн-подключение. Обновите страницу.');return;}peer=new PeerClient();peer.on('open',()=>{const conn=peer.connect('kohaku-'+roomCode,{reliable:true});bindConnection(conn);});peer.on('error',err=>{if(err.type==='peer-unavailable'){closeRoom();toast('Комната не найдена. Попросите друга создать новое приглашение.');}else toast('Не удалось подключиться. Проверьте интернет и код.');});render();}
async function copyText(value){try{await navigator.clipboard.writeText(value);toast('Скопировано. Отправьте приглашение другу.');}catch{toast(value);}}
$('new-game').onclick=()=>{if(game.history().length&&!endState()){showDialog('<h2>Начать с чистого листа?</h2><p>Текущая партия будет завершена. При желании сначала сохраните её в разделе «История».</p><div class="dialog-actions"><button id="keep-playing" class="secondary">Продолжить</button><button id="confirm-new" class="primary">Новая игра ↗</button></div>');$('keep-playing').onclick=()=>$('dialog').close();$('confirm-new').onclick=()=>{$('dialog').close();newGame();};}else newGame();};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{pending.mode=b.dataset.mode;syncSettings();});document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{pending.level=Number(b.dataset.level);syncSettings();});
document.querySelectorAll('.custom-select').forEach(root=>{const trigger=root.querySelector('.select-trigger'),menu=root.querySelector('.select-menu'),name=root.dataset.select;trigger.onclick=()=>{const opening=menu.hidden;closeSelects();menu.hidden=!opening;trigger.setAttribute('aria-expanded',String(opening));if(opening)menu.querySelector('[aria-selected="true"]')?.focus();};menu.querySelectorAll('[role="option"]').forEach(option=>option.onclick=()=>{const value=option.dataset.value;pending[name==='color'?'color':'minutes']=name==='color'?value:Number(value);setSelect(name,value);closeSelects();syncSettings();trigger.focus();});});
document.addEventListener('click',e=>{if(!e.target.closest('.custom-select'))closeSelects();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSelects();});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&document.activeElement===$('room-code'))startJoiningRoom($('room-code').value);});$('create-room').onclick=startRoom;$('join-room').onclick=()=>startJoiningRoom($('room-code').value);$('copy-room-code').onclick=()=>copyText(roomCode.toUpperCase());$('copy-room-link').onclick=()=>{const url=new URL(location.href);url.searchParams.set('room',roomCode);copyText(url.toString());};$('cancel-room').onclick=closeRoom;
for(const name of ['settings','history','diary'])$(name+'-tab').onclick=()=>openPanel(name);
$('flip').onclick=()=>{orientation=orientation==='w'?'b':'w';render();save();};
$('zoom-board').onclick=()=>{const zoomed=document.body.classList.toggle('board-zoomed');$('zoom-board').setAttribute('aria-pressed',zoomed);$('zoom-board').setAttribute('aria-label',zoomed?'Вернуть обычный размер доски':'Увеличить доску');$('zoom-board').title=zoomed?'Обычный размер доски':'Увеличить доску';};
$('fullscreen-board').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('board-column').requestFullscreen();}catch{toast('Полный экран недоступен в этом браузере.');}};
document.addEventListener('fullscreenchange',()=>{const active=document.fullscreenElement===$('board-column');$('fullscreen-board').setAttribute('aria-pressed',active);$('fullscreen-board').setAttribute('aria-label',active?'Выйти из полного экрана':'Развернуть доску на весь экран');$('fullscreen-board').title=active?'Выйти из полного экрана':'На весь экран';});
$('undo').onclick=()=>{if(result)return;tick();if(result)return;cancelWorker();let count=settings.mode==='bot'&&game.turn()===playerColor?2:1;while(count--&&game.history().length){game.undo();remaining=clockHistory.pop()||remaining;}running=game.history().length>0;lastTick=Date.now();selected=null;legal=[];hintSquares=[];save();render();requestBot();};
$('hint').onclick=()=>{if(thinking||endState())return;thinking=true;render();$('status').textContent='Ищем хорошую идею…';runWorker(3,move=>{thinking=false;if(move){hintSquares=[move.from,move.to];selected=null;legal=[];render();toast(`Попробуйте ${move.from} → ${move.to}${move.promotion?' с превращением':''}`);}});};
$('resign').onclick=()=>{showDialog('<h2>Завершить партию?</h2><p>Сдаться — тоже решение. Новая партия всегда рядом.</p><div class="dialog-actions"><button id="cancel-resign" class="secondary">Продолжить</button><button id="confirm-resign" class="primary">Сдаться ⚑</button></div>');$('cancel-resign').onclick=()=>$('dialog').close();$('confirm-resign').onclick=()=>{const color=settings.mode==='bot'||settings.mode==='online'?playerColor:game.turn();finish({title:color==='w'?'Победа чёрных':'Победа белых',detail:`${color==='w'?'Белые сдались.':'Чёрные сдались.'} Спасибо за игру.`});};};
$('export').onclick=()=>{const end=endState();game.setHeader('Event','Kohaku — спокойная партия');game.setHeader('White',settings.mode==='bot'&&playerColor==='b'?'Koi':'Player');game.setHeader('Black',settings.mode==='bot'&&playerColor==='w'?'Koi':'Player');game.setHeader('Result',!end?'*':end.title.includes('Ничья')?'1/2-1/2':end.title.includes('белых')?'1-0':'0-1');const url=URL.createObjectURL(new Blob([game.pgn()],{type:'application/x-chess-pgn'}));const a=document.createElement('a');a.href=url;a.download='kohaku-game.pgn';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('dialog-close').onclick=()=>$('dialog').close();$('dialog').addEventListener('cancel',e=>{if($('dialog').dataset.closable==='false')e.preventDefault();});
$('shop-open').onclick=()=>renderShop();$('profile-open').onclick=openProfile;
$('help').onclick=()=>showDialog('<div class="dialog-icon">♘</div><h2>Всё начинается с хода</h2><p>Нажмите на фигуру, затем на клетку назначения. Точки покажут допустимые ходы. Можно пользоваться Tab, стрелками и Enter.</p><ul><li>Чтобы сделать рокировку, переместите короля на две клетки. Ладья последует за ним.</li><li>Взятие на проходе доступно сразу после двойного хода пешки соперника.</li><li>Дойдя до последней линии, пешка может стать ферзём, ладьёй, слоном или конём.</li><li>↶ — отменить ход, ✧ — получить подсказку, ⇅ — повернуть доску.</li><li>Для игры вдвоём выберите «С другом» и нажмите «Новая игра».</li></ul><p>Часы стартуют после первого хода. Закрытие страницы приостанавливает сохранённую партию. «Фокус» приглушает фон.</p>');
$('focus').onclick=()=>{const on=document.body.classList.toggle('focus-mode');$('focus').setAttribute('aria-pressed',on);};
document.addEventListener('visibilitychange',()=>{tick();save();});window.addEventListener('pagehide',()=>{tick();save();});
initI18n();loadCosmetics();saveCosmetics();restore();const inviteCode=new URLSearchParams(location.search).get('room');if(inviteCode){pending.mode='online';$('room-code').value=inviteCode;}syncSettings();renderProfileBadge();render();requestBot();syncApprovedOrders();if(inviteCode)startJoiningRoom(inviteCode);setInterval(tick,200);setInterval(save,5000);setInterval(syncApprovedOrders,30000);
